sbi_domain_memregion_init(scratch->fw_start, scratch->fw_size,
    (SBI_DOMAIN_MEMREGION_M_READABLE |
     SBI_DOMAIN_MEMREGION_M_WRITABLE |
     SBI_DOMAIN_MEMREGION_M_EXECUTABLE |
     SBI_DOMAIN_MEMREGION_FW), ...);
/* ... later catch-all: */
sbi_domain_memregion_init(0, ~0UL,
    (SBI_DOMAIN_MEMREGION_SU_READABLE |
     SBI_DOMAIN_MEMREGION_SU_WRITABLE |
     SBI_DOMAIN_MEMREGION_SU_EXECUTABLE), ...);

pmp_idx = 0;
sbi_domain_for_each_memregion(dom, reg) {
    pmp_flags = sbi_domain_get_oldpmp_flags(reg);
    pmp_set(pmp_idx++, pmp_flags, reg->base, reg->order);
}
for(; pmp_idx < pmp_count; pmp_idx++)
    pmp_disable(pmp_idx);

/* First pass: M-only regions */
sbi_domain_for_each_memregion(dom, reg) {
    if (!SBI_DOMAIN_MEMREGION_M_ONLY_ACCESS(reg->flags)) continue;
    if (SBI_DOMAIN_MEMREGION_IS_FIRMWARE(reg->flags))
        bitmap_set(fw_smepmp_ids, pmp_idx, 1);
    sbi_hart_smepmp_set(scratch, dom, reg, pmp_idx++, pmp_flags, ...);
}
csr_set(CSR_MSECCFG, MSECCFG_MML);
/* Second pass: shared/SU regions — firmware already matched at lower index */

if (reg->flags & SBI_DOMAIN_MEMREGION_SU_READABLE)
    pmp_flags |= PMP_R;
if (reg->flags & SBI_DOMAIN_MEMREGION_SU_WRITABLE)
    pmp_flags |= PMP_W;
if (reg->flags & SBI_DOMAIN_MEMREGION_SU_EXECUTABLE)
    pmp_flags |= PMP_X;

/* Read/Write for both M and SU modes */
else if (SBI_DOMAIN_MEMREGION_IS_SURW_MRW(reg->flags))
    pmp_flags = (PMP_W | PMP_X);
/* Read only for SU mode but Read/Write for M mode */
else if (SBI_DOMAIN_MEMREGION_IS_SUR_MRW(reg->flags))
    pmp_flags = (PMP_W);

sbi_domain_for_each_memregion_idx(dom, reg, i) {
    if (SBI_DOMAIN_MEMREGION_IS_FIRMWARE(reg->flags))
        continue;
    /* ... */
    pmp_set(pmp_idx++, sbi_domain_get_oldpmp_flags(reg),
            reg->base, reg->order);
}

/* Reconfigure PMP settings for the new domain */
sbi_hart_protection_unconfigure(scratch);
sbi_hart_protection_configure(scratch);
